      let m=compact.match(/^(\d[\d.,]*)\s+(kênh|phút|giây|luồng)$/);
      if(m)out=m[1]+' '+({kênh:'channels',phút:'minutes',giây:'seconds',luồng:'workers'}[m[2]]);
      if(!out && (m=compact.match(/^Đang dùng:\s*(\d+)\s+(luồng|phút)$/)))out='In use: '+m[1]+' '+(m[2]==='luồng'?'workers':'minutes');
      if(!out && (m=compact.match(/^Đã tự đồng bộ lúc\s+(.+)$/)))out='Automatically synced at '+m[1];
      if(!out && (m=compact.match(/^Thử lại sau\s+(\d+)\s+phút$/)))out='Try again in '+m[1]+' minutes';
      if(!out && (m=compact.match(/^Đang tạm dừng gửi email để tránh vượt hạn mức Supabase\. Thử lại sau\s+(\d+)\s+phút\.$/)))out='Email sending paused to avoid Supabase rate limits. Try again in '+m[1]+' minutes.';
      if(!out && (m=compact.match(/^Đã tải Backup JSON \(([\d.,]+)\s+KB\)\. File có thể chứa URL hoặc PIN, hãy cất riêng\.$/)))out='JSON backup downloaded ('+m[1]+' KB). It may contain URLs or PINs; store it securely.';
      if(!out && (m=compact.match(/^Đã thêm (\d+) kênh mới$/)))out='Added '+m[1]+' new channels';
      if(!out && (m=compact.match(/^(\d+)\/(\d+)\s+kênh$/)))out=m[1]+'/'+m[2]+' channels';
      if(!out && (m=compact.match(/^● Sống (\d+) · ● Die (\d+) · ● Chưa rõ (\d+)$/)))out='● Live '+m[1]+' · ● Offline '+m[2]+' · ● Unknown '+m[3];
